import sys


def play(hand, original_piles):
    piles = ["E"] * 8
    for index, card in enumerate(original_piles):
        piles[index * 2] = card
    ranks = "A23456789TJQK"

    while hand:
        moved = False
        for hand_index, card in enumerate(hand):
            destination = None
            if card[0] == "K":
                for pile_index in (1, 3, 5, 7):
                    if piles[pile_index] == "E":
                        destination = pile_index
                        break
            else:
                for pile_index, top in enumerate(piles):
                    if top == "E":
                        continue
                    opposite_color = (card[1] in "DH") != (top[1] in "DH")
                    one_lower = ranks.index(card[0]) + 1 == ranks.index(top[0])
                    if opposite_color and one_lower:
                        destination = pile_index
                        break
            if destination is not None:
                piles[destination] = hand.pop(hand_index)
                moved = True
                break
        if not moved:
            break
    return piles


def main():
    hand = sys.stdin.readline().split()
    original_piles = sys.stdin.readline().split()
    print(" ".join(play(hand, original_piles)))


if __name__ == "__main__":
    main()
